using AdDatabase.API.DTOs;using AdDatabase.API.Extensions;using AdDatabase.BLL.Entities;using AdDatabase.BLL.Interfaces;using AdDatabase.BLL.Models;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;
namespace AdDatabase.API.Controllers;[Authorize,ApiController,Route("api/favorites")]public class FavoritesController(IUnitOfWork uow):ControllerBase{[HttpPost]public async Task<IActionResult>Add(FavoriteDto d,CancellationToken ct){var uid=User.UserId();var ad=await uow.Ads.GetByIdAsync(d.AdId,ct)??throw new KeyNotFoundException("Ad not found");if(await uow.Favorites.ExistsAsync(x=>x.UserId==uid&&x.AdId==d.AdId,ct))return Ok(ApiResponse<object>.Ok(new{},"Already favorited"));await uow.Favorites.AddAsync(new AdFavorite{UserId=uid,AdId=d.AdId},ct);if(ad.UserId!=uid)await uow.Notifications.AddAsync(new Notification{UserId=ad.UserId,Type="Favorite",Message=$"Your ad {ad.Title} was favorited"},ct);await uow.SaveChangesAsync(ct);return Ok(ApiResponse<object>.Ok(new{},"Favorite added"));}[HttpDelete("{adId:int}")]public async Task<IActionResult>Delete(int adId,CancellationToken ct){var uid=User.UserId();var f=(await uow.Favorites.ListAsync(x=>x.UserId==uid&&x.AdId==adId,ct)).SingleOrDefault()??throw new KeyNotFoundException("Favorite not found");uow.Favorites.Remove(f);await uow.SaveChangesAsync(ct);return Ok(ApiResponse<object>.Ok(new{},"Favorite removed"));}[HttpGet("my")]public async Task<IActionResult>Mine(CancellationToken ct){var ids=(await uow.Favorites.ListAsync(x=>x.UserId==User.UserId(),ct)).Select(x=>x.AdId).ToHashSet();return Ok(ApiResponse<List<Ad>>.Ok(await uow.Ads.ListAsync(x=>ids.Contains(x.Id),ct)));}}
